// #17fdd9 (6a993d7161f5faec9e17fdd9) — ТОЛЬКО НАСТОЯЩИЙ ТЕЛЕФОН (Pixel 6 по кабелю, Chrome): выключатель «Доступ к микрофону»
// (adb shell cmd sensor_privacy). Кейсы CALL-039, CALL-040. Вручную по команде пользователя; в обычный регресс НЕ входит.
// ТРАТИТ AI-КРЕДИТЫ (настоящий голосовой звонок gpt-realtime) и по одной официальной попытке на тест → @call @data @manual.
// Запуск: QA_REAL_PHONE=1 [QA_ANDROID_SERIAL=1A151FDF6007QZ] [QA_ADB=<путь к adb>] npx playwright test --project android --grep @manual
// Без QA_REAL_PHONE тесты пропускаются (эмулированный Pixel 7 проекта android микрофон-переключатель не поддерживает).
// Предусловия: телефон по кабелю, отладка по USB включена, adb видит устройство; Chrome на телефоне закрыт, у сайта разрешение
// «Микрофон — Разрешено» (в настройках сайта НЕ трогать: урок 04.11 — отзыв в Chrome даёт другой сценарий, R17); экран разблокирован;
// сессия business (.qa/auth/business.json) жива (npm run qa-login); в Chrome-на-телефоне не тянуть панель свайпом (pull-to-refresh).
// Мик выключается ТОЛЬКО через adb sensor_privacy; в finally всегда включается обратно.
import { _android as android, Page } from '@playwright/test';
import { execFileSync } from 'child_process';
import * as os from 'os';
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, goToPractice, goToOfficialConfirm, tap, candidateRow } from './support';
import { LIVE_STATUS } from '../call-quality/support';
import { MIC, END, START_BUTTONS, NO_RESULTS } from './mic-loss-support';

const HASH = '#17fdd9';
const ADB = process.env.QA_ADB || path.join(os.homedir(), 'Library/Android/sdk/platform-tools/adb');
const SERIAL = process.env.QA_ANDROID_SERIAL || '1A151FDF6007QZ';
const adbMic = (on: boolean) => execFileSync(ADB, ['-s', SERIAL, 'shell', 'cmd', 'sensor_privacy', on ? 'disable' : 'enable', '0', 'microphone']);

/** business (десктоп, свой контекст) создаёт кандидата; кандидат — Chrome на настоящем телефоне; → экран подтверждения. */
async function openOnPhone(browser: import('@playwright/test').Browser, tag: string) {
  const bctx = await browser.newContext({ storageState: path.resolve(__dirname, '../../../auth/business.json'), viewport: { width: 1440, height: 900 }, locale: 'he-IL' });
  const business = await bctx.newPage();
  const name = `QA-AUTO-17FDD9-PHONE-${tag}-${runStamp()}`;
  const link = await createCandidateLink(business, name);
  test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: официальная попытка на настоящем телефоне потрачена, не удаляется (сброс — איפוס admin)` });
  const [device] = (await android.devices()).filter((d) => d.serial() === SERIAL);
  expect(device, `телефон ${SERIAL} не виден (adb devices)`).toBeTruthy();
  const pctx = await device.launchBrowser({ pkg: 'com.android.chrome', locale: 'he-IL' });
  const page = await pctx.newPage();
  await goToPractice(page, link);
  await goToOfficialConfirm(page);
  return { name, business, bctx, device, pctx, page };
}

async function startLive(page: Page) {
  await tap(page, 'מוכן, מתחילים');
  await expect(page.getByTestId('call-stage')).toHaveAttribute('data-phase', 'live', { timeout: 60_000 });
  await expect(page.getByRole('status').filter({ hasText: LIVE_STATUS })).toBeVisible();
}

test.describe(`Настоящий Android: выключатель микрофона в официальном звонке (${HASH})`, () => {
  test.skip(!process.env.QA_REAL_PHONE, 'только по команде: QA_REAL_PHONE=1 (настоящий телефон + AI-кредиты)');

  test(`Т1/Т2: микрофон выкл ~10 с → ≤6 с статус + карточка с шагом «הגדרות המהירות של Android»; вкл → ≤4 с «מחובר…», карточка исчезла; звонок завершается → «הסימולציה הושלמה» @android @call @data @manual ${HASH}`, async ({ browser }) => {
    test.setTimeout(6 * 60_000);
    const s = await openOnPhone(browser, 'T1');
    try {
      await startLive(s.page);
      adbMic(false);
      const t0 = Date.now();
      // Источник: комментарий программиста 17.11 / реджект 3: на Android токен остаётся live → ловит анализатор нулей, ~3,5 с.
      await expect(s.page.getByText(MIC.cardTitle, { exact: true })).toBeVisible({ timeout: 8_000 });
      test.info().annotations.push({ type: 'mic-loss-prompt-ms', description: String(Date.now() - t0) });
      await expect(s.page.getByRole('status').filter({ hasText: MIC.status })).toBeVisible();
      await expect(s.page.getByText(MIC.cardBody)).toBeVisible();
      await expect(s.page.getByText(MIC.androidStep)).toBeVisible();
      await expect(s.page.getByTestId('call-stage')).toHaveAttribute('data-phase', 'live');
      // держим ~10 с, звонок не должен оборваться (порог сбоя — 30 с после подсказки)
      await expect(s.page.getByText(END.failTitle, { exact: true })).toHaveCount(0);
      adbMic(true);
      await expect(s.page.getByRole('status').filter({ hasText: LIVE_STATUS })).toBeVisible({ timeout: 8_000 });
      await expect(s.page.getByText(MIC.cardTitle, { exact: true })).toHaveCount(0, { timeout: 8_000 });
      await tap(s.page, 'לסיים שיחה');
      await tap(s.page, 'לאשר סיום שיחה');
      await expect(s.page.getByText(END.doneTitle, { exact: true })).toBeVisible({ timeout: 60_000 });
      expect(await s.page.locator('body').innerText()).not.toMatch(NO_RESULTS);
    } finally {
      adbMic(true);
      await s.pctx.close().catch(() => {});
      await s.bctx.close();
    }
  });

  test(`Т3: микрофон выкл >35 с → «השיחה לא הושלמה» / «תקלה טכנית», без отчёта, «פנייה לגורם אנושי»; у business «תקלה טכנית», не «הושלמה» @android @call @data @manual ${HASH}`, async ({ browser }) => {
    test.setTimeout(6 * 60_000);
    const s = await openOnPhone(browser, 'T3');
    try {
      await startLive(s.page);
      adbMic(false);
      await expect(s.page.getByText(MIC.cardTitle, { exact: true })).toBeVisible({ timeout: 8_000 });
      // Источник: реджект 3 / AC5 / FL-38 — через 30 с после подсказки technical failure, не completed.
      await expect(s.page.getByText(END.failTitle, { exact: true })).toBeVisible({ timeout: 60_000 });
      await expect(s.page.getByText(END.failReason, { exact: true })).toBeVisible();
      await expect(s.page.getByRole('button', { name: END.human }).last()).toBeVisible();
      await expect(s.page.getByRole('button', { name: START_BUTTONS })).toHaveCount(0);
      expect(await s.page.locator('body').innerText()).not.toMatch(NO_RESULTS);
      adbMic(true);
      const row = await candidateRow(s.business, s.name);
      await expect(row).toContainText('תקלה טכנית');
      await expect(row).not.toContainText('הושלמה');
    } finally {
      adbMic(true);
      await s.pctx.close().catch(() => {});
      await s.bctx.close();
    }
  });
});
